-- PT111-S4-Q12. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT111-S4-Q12$batch03$ AND q.stimulus=$batch03$Most doctors recommend that pregnant women eat a nutritious diet to promote the health of their babies. However, most babies who are born to women who ate nutritious diets while pregnant still develop at least one medical problem in their first year.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, does most to resolve the apparent discrepancy in the information above?$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT111-S4-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT111-S4-Q12$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S4-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT111-S4-Q12$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Doctors recommend nutritious diets during pregnancy to promote babies' health.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Most babies of mothers who ate nutritious diets still have a medical problem in their first year?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The recommendation does not promise a problem-free first year. It only claims the diet *helps*. Ask, "Compared to what?" If babies of mothers who did not eat well have even more problems, then the diet does help.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a comparison showing babies of well-fed mothers do better than the others.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT111-S4-Q12$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Diet while breast-feeding does not explain why the recommended pregnancy diet seems not to work.$batch03$), ($batch03$B$batch03$, $batch03$If babies of poorly fed mothers have no serious problems later in childhood, diet looks even less important.$batch03$), ($batch03$C$batch03$, $batch03$Babies of mothers without a nutritious diet have more first-year problems. Most babies have some problem either way, but the diet lowers the number. The recommendation is still sound.$batch03$), ($batch03$D$batch03$, $batch03$How serious first-year problems are compared with later ones does not show the diet helps.$batch03$), ($batch03$E$batch03$, $batch03$Doctors repeating their advice is not evidence that the advice works.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT111-S4-Q12$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
